-- Roll-up summaries: maintained on child writes, with a full recompute as backstop
-- GENERATED by src/generators/emit-postgres.js from blueprint 1.0.0 49f2c22e6c8f. Do not edit.

-- Subscription__c.Line_Count__c, Subscription__c.Total_Line_Value__c
CREATE FUNCTION app.recompute_subscription_from_subscription_line(p_ids varchar[]) RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path = app, pg_temp AS $$
  WITH s AS (
    SELECT p.id, (SELECT count(*) FROM app.subscription_line c WHERE c.subscription_id = p.id) AS line_count, (SELECT COALESCE(sum(c.line_total), 0) FROM app.subscription_line c WHERE c.subscription_id = p.id) AS total_line_value
    FROM app.subscription p WHERE p_ids IS NULL OR p.id = ANY (p_ids)
  ), u AS (
    UPDATE app.subscription p SET line_count = s.line_count, total_line_value = s.total_line_value FROM s WHERE p.id = s.id AND (p.line_count, p.total_line_value) IS DISTINCT FROM (s.line_count, s.total_line_value) RETURNING 1
  )
  SELECT count(*)::int FROM u
$$;

CREATE FUNCTION app.recompute_subscription_from_subscription_line_trg() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = app, pg_temp AS $$
BEGIN
  IF app.is_loading() THEN RETURN NULL; END IF;
  IF TG_OP = 'DELETE' THEN
    PERFORM app.recompute_subscription_from_subscription_line(ARRAY[OLD.subscription_id]);
  ELSIF TG_OP = 'UPDATE' AND OLD.subscription_id IS DISTINCT FROM NEW.subscription_id THEN
    PERFORM app.recompute_subscription_from_subscription_line(ARRAY[OLD.subscription_id, NEW.subscription_id]);
  ELSE
    PERFORM app.recompute_subscription_from_subscription_line(ARRAY[NEW.subscription_id]);
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER z90_rollup_subscription AFTER INSERT OR UPDATE OR DELETE ON app.subscription_line
  FOR EACH ROW EXECUTE FUNCTION app.recompute_subscription_from_subscription_line_trg();

-- Backstop: recompute every roll-up in this family (run after a bulk load, or nightly).
CREATE FUNCTION app.recompute_all_rollups() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = app, pg_temp AS $$
DECLARE n integer := 0;
BEGIN
  n := n + app.recompute_subscription_from_subscription_line(NULL);
  RETURN n;
END $$;
